### cli.py
"""Command-line tool skeleton: ``main(argv)`` parses arguments, runs one subcommand and returns an exit code.

    python cli.py count notes.txt          # lines / words / characters of a file
    echo "a b" | python cli.py count -     # "-" reads stdin
"""

import argparse
import sys
from collections.abc import Sequence


def count(text: str) -> dict[str, int]:
    return {"lines": len(text.splitlines()), "words": len(text.split()), "chars": len(text)}


def read_input(path: str) -> str:
    if path == "-":
        return sys.stdin.read()
    with open(path, encoding="utf-8") as f:
        return f.read()


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="cli", description="command-line tool")
    sub = parser.add_subparsers(dest="command", required=True)
    p = sub.add_parser("count", help="count lines, words and characters")
    p.add_argument("path", help="a file, or - for stdin")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        if args.command == "count":
            result = count(read_input(args.path))
            print(" ".join(f"{k}={v}" for k, v in result.items()))
            return 0
    except OSError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 2


if __name__ == "__main__":
    sys.exit(main())


### test_cli.py
import contextlib
import io
import os
import tempfile
import unittest

from cli import count, main


class CliTest(unittest.TestCase):
    def test_count(self):
        self.assertEqual(count("a b\nc\n"), {"lines": 2, "words": 3, "chars": 6})

    def test_main_reads_a_file(self):
        with tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False, dir=".") as f:
            f.write("one two\n")
        out = io.StringIO()
        try:
            with contextlib.redirect_stdout(out):
                self.assertEqual(main(["count", f.name]), 0)
        finally:
            os.unlink(f.name)
        self.assertIn("words=2", out.getvalue())

    def test_missing_file_is_an_error_exit(self):
        with contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(main(["count", "no-such-file.txt"]), 1)


if __name__ == "__main__":
    unittest.main()

